from collections import deque
from unittest import mock

from jobbot.acquisition.brightdata import BrightDataHTTPTransport


class FakeClock:
    def __init__(self):
        self.now = 0.0

    def __call__(self):
        return self.now

    def advance(self, seconds):
        self.now += seconds


class FakeSocket:
    def __init__(self, wire=b\"\", clock=None):
        self.wire = bytearray(wire)
        self.clock = clock
        self.timeout = None

    def settimeout(self, value):
        self.timeout = value

    def recv_into(self, buffer):
        count = min(len(buffer), len(self.wire))
        if count:
            buffer[:count] = self.wire[:count]
            del self.wire[:count]
        return count

    def close(self):
        pass


class FakeConnection:
    def __init__(self, wire, requests, timeout=None):
        self.sock = FakeSocket(wire)
        self.requests = requests
        self.timeout = timeout
        self.request_info = None

    def connect(self):
        pass

    def request(self, method, target, body=None, headers=None):
        self.request_info = (method, target, body, dict(headers or {}))
        self.requests.append(self)

    def close(self):
        self.sock.close()


class ConnectionFactory:
    def __init__(self, wires):
        self.wires = deque(wires)
        self.requests = []

    def __call__(self, _host, _port=None, timeout=None):
        return FakeConnection(self.wires.popleft(), self.requests, timeout)


def wire(status, headers=(), body=b\"\"):
    lines = [f\"HTTP/1.1 {status} Fixture\\r\\n\".encode(\"ascii\")]
    headers = list(headers)
    if not any(name.casefold() in {\"content-length\", \"transfer-encoding\"} for name, _ in headers):
        headers.append((\"Content-Length\", str(len(body))))
    lines.extend(f\"{name}: {value}\\r\\n\".encode(\"ascii\") for name, value in headers)
    lines.append(b\"\\r\\n\")
    return b\"\".join(lines) + body


