def connection_budget_probe():
    clock = FakeClock()
    connections = []

    class SlowHTTPSConnection:
        def __init__(self, _host, _port=None, timeout=None):
            self.timeout = timeout
            self.sock = FakeSocket()
            self.request_info = None
            self.phases = (timeout * 0.6, timeout * 0.6)
            connections.append(self)

        def connect(self):
            # Model TCP connect and TLS handshake as separate blocking phases
            # sharing HTTPSConnection's unchanged initial socket timeout.
            for seconds in self.phases:
                clock.advance(seconds)

        def request(self, method, target, body=None, headers=None):
            self.request_info = (method, target, body, headers)

        def close(self):
            self.sock.close()

    attempts = []
    try:
        with mock.patch(\"jobbot.acquisition.brightdata.API_ROOT\", \"https://fixture.invalid\"), \\
             mock.patch(\"jobbot.acquisition.brightdata.http.client.HTTPSConnection\", side_effect=SlowHTTPSConnection):
            BrightDataHTTPTransport(monotonic=clock).request(
                \"GET\", \"/source\", params={}, json_body=None, token=\"offline-only\",
                timeout_seconds=10, task_deadline=1,
                on_attempt=lambda: attempts.append(1),
            )
    except TimeoutError:
        pass
    connection = connections[0]
    assert connection.timeout == 1
    assert all(phase < connection.timeout for phase in connection.phases)
    assert clock() > 1
    assert connection.request_info is None
    return connection, len(attempts)


